//@version=6
// @description Shared math helpers for AXIS example scripts
library("AxisMath")

export const float EPS = 1e-10
export const float GOLDEN = 1.6180339887

/// Clamp x into [lo, hi]
export clamp(float x, float lo, float hi) =>
    math.max(lo, math.min(hi, x))

/// Safe divide; returns fallback when den is ~0
export nz_div(float num, float den, float fallback = 0.0) =>
    math.abs(den) < EPS ? fallback : num / den

/// Percent change vs previous value
export pct_change(float cur, float prev) =>
    nz_div(cur - prev, prev) * 100.0

/// Min-max normalize into [0, 1]
export normalize(float x, float lo, float hi) =>
    nz_div(x - lo, hi - lo)
